import { summarize } from './analyze'
import type { Summary, SummaryOptions } from './analyze'
import { MAIN } from './record'
import type { Group, MeterRecord, Tool } from './record'
import type { SessionFile } from './sessionFile'
import type { TimingSummary } from './timing'

/**
 * `/meter export`: the sessions of the last days in one file a user sends to whoever builds the team report
 * (`tools/meter/aggregate.mjs`). Each session goes by a hash of its id; agent and turn ids become `a1`, `t1` within it;
 * MCP tools become `mcp` (a server's name can say what a team uses); times count from the session's start, which
 * keeps only its day. The project is as the session file has it: a salted hash unless the user turned that off.
 */

export const EXPORT_KIND = 'oxen-meter-export'
/** Under `$.fs.write`'s 4 MiB, with room. */
export const MAX_EXPORT_BYTES = 3.5 * 1024 * 1024

export type ExportSession = {
  id: string
  tool?: Tool // Codex or Devin; none for Claude Code
  project: string
  startedDay: string // YYYY-MM-DD, UTC
  costUsd?: number
  dropped: number
  groups: Record<string, Group>
  timings: Record<string, TimingSummary>
  records?: MeterRecord[]
  recordsLeftOut?: true // left out to keep the file under its size limit; the groups still count them
}

export type ExportFile = {
  kind: typeof EXPORT_KIND
  v: 1
  label: string // the user's label, or anonymous
  version: string
  day: string // the day it was made, YYYY-MM-DD
  days: number
  settings: SummaryOptions
  summary: Summary
  sessions: ExportSession[]
}

const isMcp = (tool: string) => tool.startsWith('mcp__')

/** `records` of one session with its agents as `a1`, `a2`, its turns as `t1`, `t2`, MCP tools as `mcp`, and times from `startedAt`. */
export function anonymizeRecords(records: readonly MeterRecord[], startedAt: number): MeterRecord[] {
  const agents = new Map<string, string>()
  const turns = new Map<string, string>()
  const agent = (id: string) => {
    if (id === MAIN) {
      return MAIN
    }
    if (!agents.has(id)) {
      agents.set(id, `a${agents.size + 1}`)
    }
    return agents.get(id)!
  }
  const turn = (id: string) => {
    if (!turns.has(id)) {
      turns.set(id, `t${turns.size + 1}`)
    }
    return turns.get(id)!
  }
  const at = (t: number) => t - startedAt

  return records.map((r): MeterRecord => {
    switch (r.k) {
      case 'step':
        return { ...r, thread: agent(r.thread), turn: turn(r.turn), t0: at(r.t0), t1: at(r.t1), tools: r.tools.map(t => (isMcp(t) ? 'mcp' : t)) }
      case 'agent-call':
        return { ...r, thread: agent(r.thread), ...(r.agent !== undefined ? { agent: agent(r.agent) } : {}), t0: at(r.t0), t1: at(r.t1) }
      case 'codex':
      case 'compact':
        return { ...r, thread: agent(r.thread), t0: at(r.t0), t1: at(r.t1) }
      case 'send':
        return { ...r, thread: agent(r.thread), to: agent(r.to), t: at(r.t) }
      default:
        return { ...r, thread: agent(r.thread), t: at(r.t) }
    }
  })
}

const dayOf = (t: number) => new Date(t).toISOString().slice(0, 10)

/** The export of `sessions`, each with the id it goes by, oldest first, and their summary. */
export function exportOf(sessions: readonly { file: SessionFile; id: string }[], o: { label: string; version: string; day: string; days: number; settings: SummaryOptions }): ExportFile {
  const out = [...sessions]
    .sort((a, b) => a.file.startedAt - b.file.startedAt)
    .map(({ file, id }): ExportSession => ({
      id,
      ...(file.tool !== undefined && file.tool !== 'claude' ? { tool: file.tool } : {}),
      project: file.project,
      startedDay: dayOf(file.startedAt),
      ...(file.costUsd !== undefined ? { costUsd: file.costUsd } : {}),
      dropped: file.dropped,
      groups: file.groups,
      timings: file.timings,
      records: anonymizeRecords(file.records, file.startedAt),
    }))
  const summary = summarize(
    out.map(s => ({ sid: s.id, startedAt: 0, records: s.records ?? [], groups: s.groups, ...(s.tool !== undefined ? { tool: s.tool } : {}) })),
    o.settings,
  )

  return { kind: EXPORT_KIND, v: 1, label: o.label || 'anonymous', version: o.version, day: o.day, days: o.days, settings: o.settings, summary, sessions: out }
}

const bytes = (text: string) => new TextEncoder().encode(text).length

/** The export as text, at most `maxBytes`: the records of its oldest sessions are left out first. */
export function exportText(e: ExportFile, maxBytes = MAX_EXPORT_BYTES): string {
  const sessions = [...e.sessions]
  for (let i = 0; ; i++) {
    const text = JSON.stringify({ ...e, sessions })
    if (bytes(text) <= maxBytes || i >= sessions.length) {
      return text
    }
    const { records: _left, ...rest } = sessions[i]!
    sessions[i] = { ...rest, recordsLeftOut: true }
  }
}

files.hooks/project.ts:
/**
 * Names the records keep short and unguessable: a session's id in an export, and the project a session ran in, by
 * default a hash of its folder's name with a salt of the user's own; the name itself when the user turns hashing off.
 */

const HEX_LENGTH = 12

const baseName = (path: string) => path.replace(/[\\/]+$/, '').split(/[\\/]/).pop() ?? ''

/** The first 12 hex digits of SHA-256 over `salt` and `text`. */
export async function shortHash(salt: string, text: string): Promise<string> {
  const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(`${salt}:${text}`))

  return [...new Uint8Array(digest)]
    .map(b => b.toString(16).padStart(2, '0'))
    .join('')
    .slice(0, HEX_LENGTH)
}

export async function projectLabel(root: string, salt: string, hash: boolean): Promise<string> {
  const name = baseName(root)

  return hash ? shortHash(salt, name) : name
}

files.hooks/record.ts:
import type { Outcome } from './codex'
import { newTimings } from './timing'
import type { Timings } from './timing'

/**
 * The meter's records: one per model step, and one per event around them (a subagent's start and stop, an Agent or
 * Codex handoff, a compaction, an outcome). Metadata only: token counts, times, model and tool names, agent types.
 * No prompt, output, code, path or command is ever kept. The collector holds them in memory; the hooks add to it in
 * place and return, and a timer writes it out.
 */

/** The main conversation's thread; every other thread is a subagent's, by its agent id. */
export const MAIN = 'main'
/** The tools a session file can come from: Claude Code, where the mod records it, or Codex or Devin, imported by the CLI. */
export const TOOLS = ['claude', 'codex', 'devin'] as const
export type Tool = (typeof TOOLS)[number]
export const MAX_RECORDS = 20000
/** How many of the oldest steps go at once past MAX_RECORDS, so dropping stays rare. */
export const DROP_CHUNK = 1000

export type Usage = { in: number; out: number; cr: number; cw: number }

export type StepRecord = Usage & {
  k: 'step'
  t0: number // when the request was about to be sent: when the thread's cache was read
  t1: number // when the response was whole
  turn: string
  idx: number
  thread: string
  agentType?: string
  model: string
  effort?: string | number
  ctx: number // in + cr + cw: the context the request carried
  gapMs?: number // t0 minus the thread's previous step's t0
  msgs: number
  tools: string[]
  stop?: string
  noUsage?: true // no response, or one with no usage
  coldStart?: true // the meter judged the thread's cache cold before the request went
  keepalive?: true // a request the tool sent only to keep the cache warm (Devin)
}

export type EventRecord =
  | { k: 'agent-start' | 'agent-stop'; t: number; thread: string; agentType: string }
  | { k: 'agent-call'; t0: number; t1: number; thread: string; agent?: string; agentType?: string; model?: string; status: string; bg?: true; tokens?: number; cw5m?: number; cw1h?: number }
  | { k: 'codex'; t0: number; t1: number; thread: string; sub: string; bg?: true; failed?: true }
  | { k: 'outcome'; t: number; thread: string; outcome: Outcome }
  | { k: 'compact'; t0: number; t1: number; thread: string; trigger: string; before?: number; after?: number; usage?: Usage; stepsSeen: number }
  | { k: 'main-resume'; t: number; thread: string; idleS: number; ctx: number; expired: boolean }
  | { k: 'ttl'; t: number; thread: string; ttl: '5m' | '1h'; source: 'model-switch' | 'agent-call' }
  | { k: 'send'; t: number; thread: string; to: string; risk: boolean; gapMs?: number; ctx?: number; mode: 'off' | 'warn' | 'ask'; answer?: 'resume' | 'fresh' | 'unanswered' }
  | ({ k: 'quota'; t: number; thread: string } & QuotaReading)

export type MeterRecord = StepRecord | EventRecord

/** Every kind of record this version writes; a file's record of another kind is left out when it is read. */
export const RECORD_KINDS: ReadonlySet<string> = new Set(['step', 'agent-start', 'agent-stop', 'agent-call', 'codex', 'outcome', 'compact', 'main-resume', 'ttl', 'send', 'quota'])

/** How much of a rate-limit window is used, 0 to 100, as the tool reported it; the window by its length in minutes. */
export type QuotaReading = { windowMin: number; used: number; resetsAt?: number }

/** Where a thread stands after its last step. */
export type ThreadState = { lastT0: number; lastT1: number; lastCtx: number; lastModel: string; lastMsgs: number; steps: number; agentType?: string }

/** Exact totals of one role, agent type and model, kept apart from the records so dropping records loses nothing. */
export type Group = Usage & { steps: number }

export type Collector = {
  records: MeterRecord[]
  dropped: number
  threads: Record<string, ThreadState>
  groups: Record<string, Group>
  agentTypes: Record<string, string> // agent id to its type
  names: Record<string, string> // the name SendMessage addresses an agent by, to its id
  timings: Timings
  dirty: boolean
  compacting: number // compactions running now
  stepsInCompaction: number // steps that started while one ran
}

export const newCollector = (): Collector => ({ records: [], dropped: 0, threads: {}, groups: {}, agentTypes: {}, names: {}, timings: newTimings(), dirty: false, compacting: 0, stepsInCompaction: 0 })

export const threadOf = (agentId: string | undefined) => agentId ?? MAIN

/** How long since `thread`'s last step started, at `t0`; undefined before its first step. */
export function gapOf(c: Collector, thread: string, t0: number) {
  const last = c.threads[thread]

  return last === undefined ? undefined : t0 - last.lastT0
}

type StepInput = { turnId: string; index: number; model: string; effort?: string | number; messageCount: number; agentId?: string }
type StepResult = { toolUses: readonly { name: string }[]; serverToolUses?: readonly { name: string }[]; stopReason: string | null; usage: { input_tokens: number; output_tokens: number; cache_read_input_tokens: number; cache_creation_input_tokens: number; model: string } | null }

/** The record of one model step: `input` as `turn.step` received it, `result` as it resolved (undefined if it never did). */
export function stepRecordOf(input: StepInput, result: StepResult | undefined, t0: number, t1: number, c: Collector): StepRecord {
  const thread = threadOf(input.agentId)
  const u = result?.usage ?? undefined
  const usage = { in: u?.input_tokens ?? 0, out: u?.output_tokens ?? 0, cr: u?.cache_read_input_tokens ?? 0, cw: u?.cache_creation_input_tokens ?? 0 }
  const agentType = thread === MAIN ? undefined : c.agentTypes[thread]
  const gapMs = gapOf(c, thread, t0)
  const tools = [...(result?.toolUses ?? []), ...(result?.serverToolUses ?? [])].map(t => t.name)

  return {
    k: 'step',
    t0,
    t1,
    turn: input.turnId,
    idx: input.index,
    thread,
    ...(agentType !== undefined ? { agentType } : {}),
    model: u?.model || input.model,
    ...(input.effort !== undefined ? { effort: input.effort } : {}),
    ...usage,
    ctx: usage.in + usage.cr + usage.cw,
    ...(gapMs !== undefined ? { gapMs } : {}),
    msgs: input.messageCount,
    tools,
    ...(result?.stopReason ? { stop: result.stopReason } : {}),
    ...(u ? {} : { noUsage: true as const }),
  }
}

export const groupKey = (r: StepRecord) => `${r.thread === MAIN ? 'main' : 'subagent'}|${r.agentType ?? ''}|${r.model}`

function cap(c: Collector) {
  if (c.records.length <= MAX_RECORDS) {
    return
  }
  let left = DROP_CHUNK
  c.records = c.records.filter(r => !(r.k === 'step' && left-- > 0))
  c.dropped += DROP_CHUNK - Math.max(0, left)
}

/** Moves `r`'s thread on to it, in place. */
export function noteThread(c: Collector, r: StepRecord) {
  const steps = (c.threads[r.thread]?.steps ?? 0) + 1
  c.threads[r.thread] = { lastT0: r.t0, lastT1: r.t1, lastCtx: r.ctx, lastModel: r.model, lastMsgs: r.msgs, steps, ...(r.agentType !== undefined ? { agentType: r.agentType } : {}) }
}

/** Adds a step, in place: its record, its thread's state, and its group's totals. */
export function addStep(c: Collector, r: StepRecord) {
  c.records.push(r)
  const g = (c.groups[groupKey(r)] ??= { steps: 0, in: 0, out: 0, cr: 0, cw: 0 })
  g.steps += 1
  g.in += r.in
  g.out += r.out
  g.cr += r.cr
  g.cw += r.cw
  noteThread(c, r)
  if (c.compacting > 0) {
    c.stepsInCompaction += 1
  }
  c.dirty = true
  cap(c)
}

/** The agent type of a compaction's own request, which Codex and Devin report apart from the steps. */
export const COMPACTION_TYPE = 'compaction'

/** Adds a compaction's request to the session's totals, in place, under the agent type `compaction` of its thread's role. */
export function addCompaction(c: Collector, thread: string, model: string, u: Usage) {
  const g = (c.groups[`${thread === MAIN ? 'main' : 'subagent'}|${COMPACTION_TYPE}|${model}`] ??= { steps: 0, in: 0, out: 0, cr: 0, cw: 0 })
  g.steps += 1
  g.in += u.in
  g.out += u.out
  g.cr += u.cr
  g.cw += u.cw
  c.dirty = true
}

/** Notes the agent type an event names, in place: a subagent's start, or the Agent call that started it. */
export function noteAgentType(c: Collector, r: EventRecord) {
  if (r.k === 'agent-start') {
    c.agentTypes[r.thread] = r.agentType
  } else if (r.k === 'agent-call' && r.agent !== undefined && r.agentType !== undefined) {
    c.agentTypes[r.agent] = r.agentType
  }
}

/** Adds an event, in place. A subagent's start names its type for its later steps. */
export function addEvent(c: Collector, r: EventRecord) {
  c.records.push(r)
  noteAgentType(c, r)
  c.dirty = true
  cap(c)
}

const num = (v: unknown) => (typeof v === 'number' && Number.isFinite(v) ? v : undefined)
const str = (v: unknown) => (typeof v === 'string' && v !== '' ? v : undefined)

/**
 * The records of an Agent call that `thread` made, from its result: the agent it started, its type and model, and
 * for a finished one its tokens and the TTL its cache writes used, which is the one place a TTL is measured.
 * The prompt and the report are never read.
 */
export function agentCallOf(result: unknown, t0: number, t1: number, thread: string): EventRecord[] {
  if (result === undefined || result === null) {
    return [{ k: 'agent-call', t0, t1, thread, status: 'failed' }]
  }
  if (typeof result !== 'object') {
    return [{ k: 'agent-call', t0, t1, thread, status: 'unknown' }]
  }
  const r = result as Record<string, unknown>
  const status = str(r.status) ?? 'unknown'
  const agent = str(r.agentId) ?? str(r.agent_id)
  const agentType = str(r.agentType) ?? str(r.agent_type)
  const model = str(r.resolvedModel)
  const cache = ((r.usage as Record<string, unknown> | undefined)?.cache_creation ?? undefined) as Record<string, unknown> | undefined
  const cw5m = num(cache?.ephemeral_5m_input_tokens)
  const cw1h = num(cache?.ephemeral_1h_input_tokens)
  const tokens = num(r.totalTokens)
  const call: EventRecord = {
    k: 'agent-call',
    t0,
    t1,
    thread,
    ...(agent !== undefined ? { agent } : {}),
    ...(agentType !== undefined ? { agentType } : {}),
    ...(model !== undefined ? { model } : {}),
    status,
    ...(status !== 'completed' && status !== 'unknown' ? { bg: true as const } : {}),
    ...(tokens !== undefined ? { tokens } : {}),
    ...(cw5m !== undefined ? { cw5m } : {}),
    ...(cw1h !== undefined ? { cw1h } : {}),
  }
  const ttl = (cw1h ?? 0) > 0 ? '1h' : (cw5m ?? 0) > 0 ? '5m' : undefined
  if (ttl === undefined || agent === undefined) {
    return [call]
  }

  return [call, { k: 'ttl', t: t1, thread: agent, ttl, source: 'agent-call' }]
}

const WINDOWS: Record<string, number> = { five_hour: 300, seven_day: 10080 }

/** Claude Code's rate limits as quota readings: its 5-hour and 7-day windows; any other limit is left out. */
export function claudeQuota(limits: readonly { kind: string; percentUsed: number; resetsAt?: string }[]): QuotaReading[] {
  return limits.flatMap(l => {
    const windowMin = WINDOWS[l.kind]
    const resetsAt = l.resetsAt === undefined ? Number.NaN : Date.parse(l.resetsAt)
    return windowMin === undefined || !Number.isFinite(l.percentUsed) ? [] : [{ windowMin, used: l.percentUsed, ...(Number.isFinite(resetsAt) ? { resetsAt } : {}) }]
  })
}

/** The quota records for `readings` at `t`: one for each window whose reading moved since `records` last had it. */
export function quotaRecordsOf(records: readonly MeterRecord[], t: number, thread: string, readings: readonly QuotaReading[]): EventRecord[] {
  return readings.flatMap(q => {
    const last = records.findLast(r => r.k === 'quota' && r.windowMin === q.windowMin)
    const same = last?.k === 'quota' && last.used === q.used && last.resetsAt === q.resetsAt
    return same ? [] : [{ k: 'quota' as const, t, thread, ...q }]
  })
}

files.hooks/report.ts:
import { hitRate } from './analyze'
import type { ColdResume, GapBucket, Handoff, Summary, TtlView } from './analyze'
import { MAIN, TOOLS } from './record'
import type { Collector } from './record'
import { timingRows } from './timing'

/** One row of the pane: a label, its value, and a color when the row has a state (warm, cooling, cold). */
export type Row = { label: string; value: string; color?: string }

/** An agent as `$.agent.list()` gives it, as much as the pane needs. */
export type LiveAgent = { id: string; status: string }

/** Mid tones, so each reads on a dark terminal and a light one. */
export const COLORS = { warm: '#3fa66b', cooling: '#c98a12', cold: '#d1495b', label: '#5aa9ff', detail: '#8b93b8' }

const ENDED = new Set(['completed', 'failed', 'killed'])
const COOLING_SHARE = 0.2 // the cache counts as cooling in the last fifth of its TTL
const MIN = 60000

export function fmtTokens(n: number) {
  if (n >= 1e7) {
    return `${Math.round(n / 1e6)}M`
  }
  if (n >= 1e6) {
    return `${(n / 1e6).toFixed(1)}M`
  }
  if (n >= 1e4) {
    return `${Math.round(n / 1e3)}K`
  }

  return n >= 1e3 ? `${(n / 1e3).toFixed(1)}K` : String(Math.round(n))
}

export function fmtMin(min: number) {
  return min < 60 ? `${min}m` : `${Math.floor(min / 60)}h${String(min % 60).padStart(2, '0')}m`
}

/** A model id without its `claude-` prefix and its date. */
export const shortModel = (model: string) => model.replace(/^claude-/, '').replace(/-\d{8}$/, '')

const pct = (part: number, whole: number) => (whole > 0 ? Math.round((part / whole) * 100) : 0)

/** A subagent's label: its type, or `agent`, and the last four letters or digits of its id. */
export const agentLabel = (id: string, type: string | undefined) => `${type ?? 'agent'} ${id.replace(/[^A-Za-z0-9]/g, '').slice(-4)}`

/** A thread's label: `main`, or its agent's. */
export const threadLabel = (thread: string, c: Collector) => (thread === MAIN ? 'main' : agentLabel(thread, c.agentTypes[thread]))

/** A thread's row: its model and context, how long since its cache was read, and how long the cache has left. */
function threadRow(label: string, c: Collector, id: string, now: number, ttlMin: number): Row {
  const t = c.threads[id]
  if (t === undefined) {
    return { label, value: 'no step yet' }
  }
  const idle = now - t.lastT0
  const left = ttlMin * MIN - idle
  const state = left <= 0 ? 'cold' : left <= ttlMin * MIN * COOLING_SHARE ? 'cooling' : 'warm'
  const cache = state === 'cold' ? 'cold' : `${state} ~${fmtMin(Math.ceil(left / MIN))}`

  return { label, value: `${shortModel(t.lastModel)} · ctx ${fmtTokens(t.lastCtx)} · read ${fmtMin(Math.floor(idle / MIN))} ago · ${cache}`, color: COLORS[state] }
}

/** What the pane adds once the meter has it: the session's summary, and where its file goes. */
export type PaneExtras = { summary?: Summary; files?: string }

/**
 * The pane's rows at `now`: the cache over every step, the steps by role, the token equivalent, TTLs and cold resumes,
 * each live thread, where the file goes, the handoffs and outcomes, and the meter's own hook times.
 */
export function paneRows(c: Collector, live: readonly LiveAgent[], now: number, ttlMin: { main: number; subagent: number }, more: PaneExtras = {}): Row[] {
  const groups = Object.entries(c.groups)
  if (groups.length === 0) {
    return [{ label: 'Cache', value: 'no model step yet' }]
  }
  const sum = { steps: 0, in: 0, out: 0, cr: 0, cw: 0, main: 0, subagent: 0 }
  for (const [key, g] of groups) {
    sum.steps += g.steps
    sum.in += g.in
    sum.out += g.out
    sum.cr += g.cr
    sum.cw += g.cw
    sum[key.startsWith('main|') ? 'main' : 'subagent'] += g.steps
  }
  const rows: Row[] = [
    { label: 'Cache', value: `hit ${pct(sum.cr, sum.cr + sum.cw + sum.in)}% · read ${fmtTokens(sum.cr)} · written ${fmtTokens(sum.cw)} · uncached ${fmtTokens(sum.in)} · output ${fmtTokens(sum.out)}` },
    { label: 'Steps', value: [sum.main > 0 ? `${sum.main} main` : '', sum.subagent > 0 ? `${sum.subagent} subagent` : ''].filter(Boolean).join(' · ') },
  ]
  const summary = more.summary
  if (summary) {
    rows.push({ label: 'Token eq.', value: eqText(summary) }, { label: 'TTL', value: ttlText(summary.ttl) })
    if (summary.cold.length > 0) {
      rows.push({ label: 'Cold', value: `${plural(summary.cold.length, 'cold resume')}: ${fmtTokens(summary.cold.reduce((n, r) => n + r.extra, 0))} eq beyond a read`, color: COLORS.cold })
    }
  }
  if (c.threads[MAIN]) {
    rows.push(threadRow('main', c, MAIN, now, ttlMin.main))
  }
  for (const a of live) {
    if (!ENDED.has(a.status)) {
      rows.push(threadRow(agentLabel(a.id, c.agentTypes[a.id]), c, a.id, now, ttlMin.subagent))
    }
  }
  if (more.files !== undefined) {
    rows.push({ label: 'Files', value: more.files })
  }

  return [...rows, ...eventRows(c), ...timingRows(c.timings).map(t => ({ label: t.hook, value: t.text }))]
}

const plural = (n: number, word: string) => `${n} ${word}${n === 1 ? '' : 's'}`
const notes = (parts: string[]) => (parts.length > 0 ? ` (${parts.join(', ')})` : '')

/** The rows for what happened around the steps: handoffs to subagents and Codex, outcomes, compactions. */
function eventRows(c: Collector): Row[] {
  const n = { agent: 0, agentBg: 0, codex: 0, codexBg: 0, codexFailed: 0, commit: 0, pr: 0 }
  const compactions: string[] = []
  for (const r of c.records) {
    if (r.k === 'agent-call') {
      n.agent += 1
      n.agentBg += r.bg ? 1 : 0
    } else if (r.k === 'codex') {
      n.codex += 1
      n.codexBg += r.bg ? 1 : 0
      n.codexFailed += r.failed ? 1 : 0
    } else if (r.k === 'outcome') {
      n[r.outcome] += 1
    } else if (r.k === 'compact') {
      compactions.push(r.before !== undefined && r.after !== undefined ? `${fmtTokens(r.before)} → ${fmtTokens(r.after)}` : r.trigger)
    }
  }
  const rows: Row[] = []
  const handoffs = [
    n.agent > 0 ? `${n.agent} Agent${notes(n.agentBg > 0 ? [`${n.agentBg} background`] : [])}` : '',
    n.codex > 0 ? `${n.codex} Codex${notes([...(n.codexBg > 0 ? [`${n.codexBg} background`] : []), ...(n.codexFailed > 0 ? [`${n.codexFailed} failed`] : [])])}` : '',
  ].filter(Boolean)
  if (handoffs.length > 0) {
    rows.push({ label: 'Handoffs', value: handoffs.join(' · ') })
  }
  if (n.commit + n.pr > 0) {
    rows.push({ label: 'Outcomes', value: [n.commit > 0 ? plural(n.commit, 'commit') : '', n.pr > 0 ? `${n.pr} PR${n.pr === 1 ? '' : 's'}` : ''].filter(Boolean).join(' · ') })
  }
  if (compactions.length > 0) {
    rows.push({ label: 'Compactions', value: `${compactions.length}: ${compactions.slice(-3).join(', ')}` })
  }

  return rows
}

/** The rows as plain text, one `label: value` a line, for where no pane shows. */
export const rowsText = (rows: readonly Row[]) => rows.map(r => `${r.label}: ${r.value}`).join('\n')

const eqText = (s: Summary) => `${fmtTokens(s.eq)}: main ${fmtTokens(s.byRole.main.eq)} · subagent ${fmtTokens(s.byRole.subagent.eq)}`

/** How long `ms` is, in seconds under a minute, else as fmtMin does. */
export const fmtDur = (ms: number) => (ms < 60000 ? `${Math.round(ms / 1000)}s` : fmtMin(Math.round(ms / 60000)))

function ttlOne(t: TtlView) {
  const ttl = t.min >= 60 ? '1h' : '5m'
  if (t.source === 'setting') {
    return `${t.role} ${ttl} (setting)`
  }
  if (t.source === 'measured') {
    return `${t.role} ${ttl} (measured: ${t.measured['5m'] + t.measured['1h']})`
  }
  const seen = [
    t.warm > 0 ? `${t.warm} warm up to ${fmtDur(t.longestWarmMs ?? 0)}` : '',
    t.cold > 0 ? `${t.cold} cold from ${fmtDur(t.shortestColdMs ?? 0)}` : '',
  ].filter(Boolean)

  return `${t.role} ${ttl} (${t.source}: ${seen.length > 0 ? seen.join(', ') : 'no samples'})`
}

const ttlText = (ttl: Summary['ttl']) => `${ttlOne(ttl.main)} · ${ttlOne(ttl.subagent)}`

const median = (values: number[]) => {
  const sorted = [...values].sort((a, b) => a - b)
  const mid = Math.floor(sorted.length / 2)
  return sorted.length === 0 ? undefined : sorted.length % 2 ? sorted[mid]! : (sorted[mid - 1]! + sorted[mid]!) / 2
}

const pad = (label: string) => label.padEnd(10)
const INDENT = ' '.repeat(11)

/** When `t` was, in UTC: the mod has no time zone to read. */
const utc = (t: number) => `${new Date(t).toISOString().slice(0, 16).replace('T', ' ')} UTC`

function coldLine(r: ColdResume) {
  const who = r.role === 'main' ? (r.model === '' ? 'main (resumed)' : `main  ${shortModel(r.model)}`) : `${agentLabel(r.thread, r.agentType)}  ${shortModel(r.model)}`

  return `${utc(r.t)}  ${r.tool !== undefined ? `${r.tool} ` : ''}${who}  idle ${fmtDur(r.gapMs)}  ${r.tool !== undefined ? 'sent again' : 'wrote'} ${fmtTokens(r.cw)}  +${fmtTokens(r.extra)} eq`
}

/** A gap bucket's span, in minutes up to an hour and in hours past it: `5–10m`, `30–60m`, `1–2h`, `6h+`. */
function spanOf(b: GapBucket) {
  if (b.toMin === undefined) {
    return b.fromMin >= 60 ? `${b.fromMin / 60}h+` : `${b.fromMin}m+`
  }

  return b.toMin <= 60 ? `${b.fromMin}–${b.toMin}m` : `${b.fromMin / 60}–${b.toMin / 60}h`
}

/** One gap curve: each bucket with samples, as warm over all. */
function gapLine(key: string, curve: readonly GapBucket[]) {
  const [tool, family] = key.split('|')
  const parts = curve.filter(b => b.warm + b.cold > 0).map((b, i) => `${spanOf(b)} ${b.warm}/${b.warm + b.cold}${i === 0 ? ' warm' : ''}`)

  return `${tool} ${family}: ${parts.join(' · ')}`
}

/** A rate-limit window by its length: `5h`, `7d`, else minutes. */
const windowName = (min: number) => (min % 1440 === 0 ? `${min / 1440}d` : min % 60 === 0 ? `${min / 60}h` : `${min}m`)

function quotaText(quota: Summary['quota']) {
  return Object.entries(quota)
    .map(([key, points]) => {
      const [tool, windowMin] = key.split('|')
      const p = Math.round(points * 10) / 10
      return `${tool} ${windowName(Number(windowMin))} +${p} pt${p === 1 ? '' : 's'}`
    })
    .join(' · ')
}

function handoffText(all: readonly Handoff[]) {
  const part = (kind: Handoff['kind'], one: string, many: string) => {
    const own = all.filter(h => h.kind === kind)
    if (own.length === 0) {
      return ''
    }
    const bg = own.filter(h => h.bg).length
    const back = median(own.flatMap(h => (h.workMs !== undefined ? [h.workMs] : [])))
    return `${own.length} ${own.length === 1 ? one : many}${bg > 0 ? ` (${bg} background)` : ''}${back !== undefined ? `, median ${fmtDur(back)} back` : ''}`
  }
  const react = median(all.flatMap(h => (h.reactMs !== undefined ? [h.reactMs] : [])))

  return [part('agent', 'Agent', 'Agent'), part('codex', 'Codex', 'Codex'), part('resume', 'resume', 'resumes'), react !== undefined ? `next handoff median ${fmtDur(react)}` : ''].filter(Boolean).join(' · ')
}

const FLAG_NAMES = { 'context-bloat': 'context bloat', 'big-first-prefix': 'big first prefix', 'expensive-short': 'short task on an expensive model' } as const
const TOP_COLD = 5

/** `/meter report`: what `s` adds up to over the last `days`, one row a line, the cold resumes that cost most first. */
export function reportText(s: Summary, o: { days: number; skipped: number }): string {
  if (s.sessions === 0) {
    return `No session in the last ${plural(o.days, 'day')}.`
  }
  const byEq = <T extends { eq: number }>(rec: Record<string, T>) => Object.entries(rec).sort((a, b) => b[1].eq - a[1].eq)
  const tools = TOOLS.flatMap(tool => (s.byTool[tool] !== undefined ? [[tool, s.byTool[tool]] as const] : []))
  const lines = [
    `${plural(s.sessions, 'session')} in the last ${plural(o.days, 'day')}${o.skipped > 0 ? ` (${plural(o.skipped, 'emptied file')} skipped)` : ''}`,
    ...(tools.length > 1 || (tools.length === 1 && tools[0]![0] !== 'claude') ? [`${pad('Tools')} ${tools.map(([tool, g]) => `${tool} ${plural(g.sessions, 'session')}, ${fmtTokens(g.eq)} eq`).join(' · ')}`] : []),
    `${pad('Cache')} hit ${pct(s.totals.cr, s.totals.cr + s.totals.cw + s.totals.in)}% · read ${fmtTokens(s.totals.cr)} · written ${fmtTokens(s.totals.cw)} · uncached ${fmtTokens(s.totals.in)} · output ${fmtTokens(s.totals.out)}`,
    `${pad('Token eq.')} ${eqText(s)}`,
    `${pad('Models')} ${byEq(s.byModel).map(([m, g]) => `${shortModel(m)} hit ${Math.round(hitRate(g) * 100)}%, ${fmtTokens(g.eq)} eq`).join(' · ')}`,
    `${pad('Agents')} ${byEq(s.byAgentType).map(([a, g], i) => `${a} ${fmtTokens(g.eq)}${i === 0 ? ' eq' : ''}`).join(' · ')}`,
    ...(s.byTool.claude !== undefined ? [`${pad('TTL')} ${ttlText(s.ttl)}`] : []),
    ...Object.entries(s.gaps).map(([key, curve], i) => `${i === 0 ? pad('Gaps') : INDENT.slice(1)} ${gapLine(key, curve)}`),
    ...(s.keepalive.steps > 0 ? [`${pad('Keepalive')} ${plural(s.keepalive.steps, 'ping')}, ${fmtTokens(s.keepalive.eq)} eq`] : []),
    ...(s.compaction.count > 0 ? [`${pad('Compaction')} ${s.compaction.count}${s.compaction.eq > 0 ? `, ${fmtTokens(s.compaction.eq)} eq` : ''}`] : []),
    ...(Object.keys(s.quota).length > 0 ? [`${pad('Quota')} ${quotaText(s.quota)}`] : []),
  ]
  if (s.cold.length > 0) {
    const written = s.cold.reduce((n, r) => n + r.cw, 0)
    const extra = s.cold.reduce((n, r) => n + r.extra, 0)
    lines.push(`${pad('Cold')} ${plural(s.cold.length, 'cold resume')}: ${fmtTokens(written)} written again, ${fmtTokens(extra)} eq beyond a read`)
    for (const r of [...s.cold].sort((a, b) => b.extra - a.extra).slice(0, TOP_COLD)) {
      lines.push(`${INDENT}${coldLine(r)}`)
    }
  }
  const handoffs = handoffText(s.handoffs)
  if (handoffs !== '') {
    lines.push(`${pad('Handoffs')} ${handoffs}`)
  }
  const flags = (Object.keys(FLAG_NAMES) as (keyof typeof FLAG_NAMES)[]).flatMap(k => {
    const n = s.flags.filter(f => f.kind === k).length
    return n > 0 ? [`${n} ${FLAG_NAMES[k]}`] : []
  })
  if (flags.length > 0) {
    lines.push(`${pad('Flags')} ${flags.join(' · ')}`)
  }

  return lines.join('\n')
}

/** Where the session's file goes, as the meter last wrote it. */
export type FilesState = { root: string | undefined; savedAt?: number; error?: string }

/** The pane's files row: where the session is saved, or why it is not. */
export function filesText(f: FilesState, now: number) {
  if (f.root === undefined) {
    return 'not saved: set Data folder in /plugin configure oxen-meter@oxen-pet'
  }
  if (f.error !== undefined) {
    return `not saved: ${f.error}`
  }

  return f.savedAt === undefined ? `not saved yet: ${f.root}/sessions` : `saved ${fmtMin(Math.floor((now - f.savedAt) / MIN))} ago to ${f.root}/sessions`
}

